import csv
import json

def load_data(path):
    data = []
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            data.append(row)
    return data

def clean_data(data):
    out = []
    for item in data:
        if item.get('name') is None:
            continue
        item['name'] = item['name'].strip()
        out.append(item)
    return out

def aggregate(data):
    result = {}
    for item in data:
        key = item.get('category', 'other')
        result[key] = result.get(key, 0) + 1
    return result
